    36  LLVMFuzzerTestOneInput(const uint8_t * data, size_t size)
    37  {
    38      af_gb_init();
    39
    40      int argc = (af_get_short(&data, &size) % 99) + 1;
    41      char **argv = malloc(argc * sizeof(*argv));
    42      for (int i = 0; i < argc; i++) {
    43          argv[i] = af_gb_get_null_terminated(&data, &size);
    44          if (!argv[i])
    45              goto free_argv;
    46      }
    47
    48      netsnmp_session *ss = SNMP_MALLOC_TYPEDEF(netsnmp_session);
    49
    50      snmp_parse_args(argc, argv, ss, "", NULL);
    51
    52      snmp_close(ss);
    53      netsnmp_cleanup_session(ss);
    54      free(ss);
    55
    56  free_argv:
    57      free(argv);
    58
    59      af_gb_cleanup();
    60
    61      return 0;
    62  }
